  process.exit();
}
const readLine = () => inputString[currentLine++];

process.stdin.on('data', inputStdin => inputString += inputStdin);
process.stdin.on('end', runMain);
process.on('SIGINT', runMain);

function main() {
  const [n, t] = readLine().split(' ').map(num => Number(num));
  const str = readLine().split('');
  for (let i = 0; i < t; i++) {
    let j = 0;
    while (j < n - 1) {
      if (str[j] === 'B' && str[j + 1] === 'G') {
        str[j] = 'G';
        str[j + 1] = 'B';
        j++;
      }
      j++;
    }
  }
  console.log(str.join(''));
}
